<script lang="ts">
 import { api } from '$lib/api';import { t } from '$lib/i18n';import { Input } from '$lib/components/ui/input';import { Label } from '$lib/components/ui/label';import { Button } from '$lib/components/ui/button';import { signInWithPasskey } from '$lib/native-auth';
 let code=$state(''),error=$state(''),busy=$state(false);
 async function submit(passkey=false){busy=true;error='';try{if(passkey)await signInWithPasskey();else await api.post('/v1/auth/mfa/verify',{code});window.location.assign('/admin');}catch(e){error=e instanceof Error?e.message:$t('nativeAuth.failed');}finally{busy=false;}}
</script>
<div class="flex min-h-screen items-center justify-center bg-muted/20 p-4"><form class="w-full max-w-sm space-y-5 rounded-xl border bg-card p-6" onsubmit={e=>{e.preventDefault();submit();}}><div><h1 class="text-xl font-semibold">{$t('nativeAuth.verifyTitle')}</h1><p class="mt-1 text-sm text-muted-foreground">{$t('nativeAuth.challengeHint')}</p></div><div class="space-y-2"><Label for="mfa-code">{$t('nativeAuth.code')}</Label><Input id="mfa-code" bind:value={code} autocomplete="one-time-code" required /></div>{#if error}<p role="alert" class="text-sm text-destructive">{error}</p>{/if}<Button type="submit" class="w-full" disabled={busy}>{$t('nativeAuth.verify')}</Button><Button type="button" variant="outline" class="w-full" disabled={busy} onclick={()=>submit(true)}>{$t('nativeAuth.usePasskey')}</Button></form></div>
